"""العربية — التفاصيل، prophets_c_1 (50 سؤالًا)."""

D = {
"prophets_151": "جاء الأمر في سورة البقرة: «يا آدم اسكن أنت وزوجك الجنة وكلا منها رغدًا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين» (2:35). وقد جاء مباشرة بعد سجود الملائكة لآدم وإباء إبليس (2:34)، ومباشرة قبل أن يزلّهما الشيطان (2:36). ويتعلم المسلم أن الطاعة تُختبر عند الحد الواحد الذي يضعه الله، لا في السعة التي يبيحها.",

"prophets_152": "تقول الآية: «فتلقى آدم من ربه كلمات فتاب عليه إنه هو التواب الرحيم» (2:37). وتحفظ سورة الأعراف دعاء آدم وزوجه: «ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين» (7:23). ويتعلم المسلم أن طريق العودة إلى الله فُتح لأول إنسان.",

"prophets_153": "تقول الآية: «إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون» (3:59). وكانت سورة آل عمران قد حكت للتوّ مولد عيسى، والآية التالية تختم الحجة: «الحق من ربك فلا تكن من الممترين» (3:60). ويأخذ المسلم منها أن عيسى عبد مخلوق ورسول، وأن العجيب في المولد يدل على الخالق.",

"prophets_154": "تقول سورة مريم: «واذكر في الكتاب إدريس إنه كان صديقًا نبيًا ورفعناه مكانًا عليًا» (19:56-57). وهو يختم سلسلة من الأنبياء تأمر السورةُ النبيَّ ﷺ بذكرهم: إبراهيم (19:41)، وموسى (19:51)، وإسماعيل (19:54)، ثم إدريس. ثم تجمعهم السورة كلهم فيمن أنعم الله عليهم، الذين خرّوا سجدًا وبكيًا إذا تُليت عليهم آياته (19:58). ويتعلم المسلم أن إدريس أُكرم بأمرين ذُكرا معًا: الصدق والنبوة.",

"prophets_155": "كلمات نوح في سورة هود: «اركبوا فيها بسم الله مجراها ومرساها إن ربي لغفور رحيم» (11:41). وفي الآية التي قبلها فار التنور علامةً على بدء الطوفان، مع الأمر بأن يحمل من كل زوجين اثنين والقليل الذين آمنوا (11:40). ويتعلم المسلم من نوح أن يبدأ كل رحلة باسم الله، واثقًا به في الانطلاق والوصول.",

"prophets_156": "يختم هذا الدعاء سورة نوح: «رب لا تذر على الأرض من الكافرين ديارًا إنك إن تذرهم يضلوا عبادك ولا يلدوا إلا فاجرًا كفارًا» (71:26-27). وقد جاء بعد أن قال نوح لربه إنه دعا قومه ليلًا ونهارًا، وإن دعاءه لم يزدهم إلا فرارًا (71:5-6)؛ والقرآن يحسب لبثه فيهم ألف سنة إلا خمسين عامًا (29:14). ويتعلم المسلم أن نوحًا لم يسأل هذا إلا بعد عمر من الدعوة الصابرة.",

"prophets_157": "الأمر في سورة المؤمنون: «اصنع الفلك بأعيننا ووحينا فإذا جاء أمرنا وفار التنور فاسلك فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول منهم» (23:27). وقبل ذلك مباشرة لم يرَ فيه قومه إلا بشرًا مثلهم، فدعا: «رب انصرني بما كذبون» (23:26). ويتعلم المسلم أن نجاة الله جاءت بتعليمات دقيقة، وأن نوحًا تلقاها بالحمد (23:28).",

"prophets_158": "يقول هود لعاد في سورة الأعراف: «واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطة فاذكروا آلاء الله لعلكم تفلحون» (7:69). وكان قد بدأ كما يبدأ كل نبي: «يا قوم اعبدوا الله ما لكم من إله غيره» (7:65)، فأجاب الملأ أنهم يرونه في سفاهة (7:66). ويتعلم المسلم أن قوة الأمة نعمة تُذكر، وأن ذكرها هو طريق الفلاح.",

"prophets_159": "تقول سورة الحاقة: «وأما عاد فأهلكوا بريح صرصر عاتية سخرها عليهم سبع ليال وثمانية أيام حسومًا فترى القوم فيها صرعى كأنهم أعجاز نخل خاوية» (69:6-7). وتقرنهم السورة بثمود الذين «أهلكوا بالطاغية» (69:5). ويتعلم المسلم أن الريح التي تخدمنا كل يوم جند من جنود الله، وأن لا قوة تقف أمامه.",

"prophets_160": "يسأل هود في سورة الشعراء: «أتبنون بكل ريع آية تعبثون وتتخذون مصانع لعلكم تخلدون» (26:128-129). وكان قد افتتح بالنداء الذي تجعله السورة لكل رسول: «ألا تتقون» (26:124)، ثم يمضي فيسمّي الذي أمدّهم بأنعام وبنين وجنات وعيون (26:132-134). ويتعلم المسلم أن يستعمل المال للحاجة والشكر لا للتباهي، متذكرًا أن الأرض ليست دار بقاء.",

"prophets_161": "يقول صالح لثمود في سورة الأعراف: «واذكروا إذ جعلكم خلفاء من بعد عاد وبوأكم في الأرض تتخذون من سهولها قصورًا وتنحتون الجبال بيوتًا فاذكروا آلاء الله ولا تعثوا في الأرض مفسدين» (7:74). وقبل ذلك مباشرة كان قد أراهم ناقة الله آيةً، وأمرهم ألا يمسوها بسوء (7:73). ويتعلم المسلم أن صنعة الأمة من الله، وأن الجواب الصحيح هو الشكر.",

"prophets_162": "يقول الله لصالح في سورة القمر: «إنا مرسلو الناقة فتنة لهم فارتقبهم واصطبر ونبئهم أن الماء قسمة بينهم كل شرب محتضر» (54:27-28). وكانت ثمود قد أبت أن تتبع «بشرًا منا واحدًا» ووصفت صالحًا بأنه كذاب أشر (54:24-25). فسقطوا في الفتنة: نادوا صاحبهم فتعاطى فعقر (54:29). ويتعلم المسلم أن آية الله اختبار أيضًا لكيفية التعامل معها.",

"prophets_163": "تحكي سورة الأعراف النهاية: «فأخذتهم الرجفة فأصبحوا في دارهم جاثمين» (7:78). والآية التي قبلها تعطي السبب: عقروا الناقة وعتوا عن أمر ربهم وتحدّوا صالحًا: «ائتنا بما تعدنا إن كنت من المرسلين» (7:77). ويتعلم المسلم أن العذاب المطلوب استهزاءً قد يأتي، وأن نصيحة النبي كانت الحماية الحقيقية.",

"prophets_164": "تحفظ سورة الشعراء: «إذ قال لهم أخوهم لوط ألا تتقون إني لكم رسول أمين فاتقوا الله وأطيعون وما أسألكم عليه من أجر إن أجري إلا على رب العالمين» (26:161-164). وتجعل السورة الكلمات الافتتاحية نفسها لنوح وهود وصالح، وكل واحد منهم يُسمّى «أخوهم» كذلك. ويتعلم المسلم أن لوطًا جاء قومه أخًا، بالدعوة التي جاء بها كل رسول.",

"prophets_165": "تقول الملائكة للوط في سورة هود: «إنا رسل ربك لن يصلوا إليك فأسر بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك إنه مصيبها ما أصابهم إن موعدهم الصبح» (11:81). وعند الصبح جُعل عاليها سافلها وأُمطرت حجارة من سجيل (11:82). ويتعلم المسلم أن طاعة أوامر الله من غير التفات كانت هي المخرج.",

"prophets_166": "تقول سورة هود: «وإلى مدين أخاهم شعيبًا قال يا قوم اعبدوا الله ما لكم من إله غيره ولا تنقصوا المكيال والميزان إني أراكم بخير وإني أخاف عليكم عذاب يوم محيط» (11:84). ثم يمضي: «أوفوا المكيال والميزان بالقسط ولا تبخسوا الناس أشياءهم» (11:85). فعبادة الله وحده وصدق الموازين يجتمعان في نفس واحد. ويتعلم المسلم أن العدل في المعاملة جزء من الإيمان.",

"prophets_167": "يقول شعيب في سورة هود: «وما أريد أن أخالفكم إلى ما أنهاكم عنه إن أريد إلا الإصلاح ما استطعت وما توفيقي إلا بالله عليه توكلت وإليه أنيب» (11:88). وكان قومه قد سخروا منه للتوّ: «أصلاتك تأمرك أن نترك ما يعبد آباؤنا» (11:87). ويتعلم المسلم أن من يدعو إلى الخير يجب أن يعمل به أولًا، وأن يعتمد على الله في النتيجة.",

"prophets_168": "تقول سورة البقرة: «وإذ ابتلى إبراهيم ربه بكلمات فأتمهن قال إني جاعلك للناس إمامًا قال ومن ذريتي قال لا ينال عهدي الظالمين» (2:124). والآيات التي بعدها تبين ما عنته تلك الإمامة: البيت جُعل مثابة للناس وأمنًا، وإبراهيم وإسماعيل يرفعان قواعده داعيَين «ربنا تقبل منا» (2:125-127). ويتعلم المسلم أن الإمامة في الدين تُعطى على طاعة أُتمّت، لا تُورث بالدم.",

"prophets_169": "تحكيها سورة البقرة: «إذ قال إبراهيم ربي الذي يحيي ويميت قال أنا أحيي وأميت قال إبراهيم فإن الله يأتي بالشمس من المشرق فأت بها من المغرب فبهت الذي كفر» (2:258). وتقول الآية إن الرجل حاجّ «أن آتاه الله الملك» وتتركه بلا اسم. ويتعلم المسلم أن يرد على الدعوى الباطلة بحجة واضحة لا تستطيع قوة على الأرض أن تحاكيها.",

"prophets_170": "نص الأمر: «وأذن في الناس بالحج يأتوك رجالًا وعلى كل ضامر يأتين من كل فج عميق» (22:27). والآية التي قبلها تمهد المشهد: بوّأ الله لإبراهيم مكان البيت مع الأمر بألا يشرك به شيئًا وأن يطهره للطائفين والقائمين والركع السجود (22:26). ويتعلم المسلم أن الحج دعوة أذّن بها إبراهيم أول مرة، وكل حاج اليوم يلبيها.",

"prophets_171": "تحكيها سورة الذاريات: «إذ دخلوا عليه فقالوا سلامًا قال سلام قوم منكرون فراغ إلى أهله فجاء بعجل سمين فقربه إليهم قال ألا تأكلون» (51:24-27). فلما لم تصل أيديهم إليه أوجس منهم خيفة؛ قالوا: «لا تخف»، وبشروه بغلام عليم (51:28). ويتعلم المسلم الضيافة من إبراهيم: رد التحية، والذهاب في هدوء، والمجيء بالأفضل، وتقريبه إليهم، والدعوة بلطف.",

"prophets_172": "تقول سورة الممتحنة: «قد كانت لكم أسوة حسنة في إبراهيم والذين معه إذ قالوا لقومهم إنا برآء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء أبدًا حتى تؤمنوا بالله وحده» (60:4). وتنتهي الآية نفسها بدعائهم: «ربنا عليك توكلنا وإليك أنبنا» (60:4). ويتعلم المسلم أن الولاء لله أولًا.",

"prophets_173": "يفتتح الدعاء: «رب اجعل هذا البلد آمنًا واجنبني وبني أن نعبد الأصنام رب إنهن أضللن كثيرًا من الناس» (14:35-36). ثم يمضي إبراهيم فيقول إنه أسكن من ذريته بواد غير ذي زرع عند بيت الله المحرم، ويسأل أن تهوي أفئدة من الناس إليهم وأن يُرزقوا من الثمرات (14:37). ويتعلم المسلم من إبراهيم ما يسأله لأولاده قبل الطعام والراحة: أن يعبدوا الله وحده.",

"prophets_174": "تحفظ سورة الصافات: «وقال إني ذاهب إلى ربي سيهدين رب هب لي من الصالحين فبشرناه بغلام حليم» (37:99-101). وتأتي الكلمات مباشرة بعد أن حاول قومه إحراقه وقد غُلبوا في الجدال حول الأصنام التي كسّرها: «فأرادوا به كيدًا فجعلناهم الأسفلين» (37:98). ويتعلم المسلم أن مفارقة القوم في سبيل الله رحلة نحو الهداية، وأن أول ثمارها كان ابنًا صالحًا.",

"prophets_175": "تقول سورة مريم: «واذكر في الكتاب إسماعيل إنه كان صادق الوعد وكان رسولًا نبيًا وكان يأمر أهله بالصلاة والزكاة وكان عند ربه مرضيًا» (19:54-55). وهو يرد في سلسلة أنبياء السورة بعد موسى وهارون (19:51-53) وقبل إدريس (19:56). ويتعلم المسلم أن الوفاء بالوعد من علامات النبوة، وأن الصلاة والزكاة تبدآن في البيت.",

"prophets_176": "يقول يعقوب في سورة يوسف: «يا بني لا تقصص رؤياك على إخوتك فيكيدوا لك كيدًا إن الشيطان للإنسان عدو مبين» (12:5). وكان يوسف قد قال له للتوّ: «يا أبت إني رأيت أحد عشر كوكبًا والشمس والقمر رأيتهم لي ساجدين» (12:4). وفي آخر السورة يخرّ أهل يوسف له سجدًا (12:100). ويتعلم المسلم أن يصون النعمة من الحسد وأن يثق بالله في تحقيقها.",

"prophets_177": "تحفظ سورة يوسف: «وشهد شاهد من أهلها إن كان قميصه قُدّ من قُبُل فصدقت وهو من الكاذبين وإن كان قميصه قُدّ من دُبُر فكذبت وهو من الصادقين» (12:26-27). والآية التالية تحسم الأمر: «فلما رأى قميصه قُدّ من دُبُر قال إنه من كيدكن» (12:28). ويتعلم المسلم أن الله أظهر براءة يوسف بعلامة بينة.",

"prophets_178": "تحكيها سورة يوسف: «أرسلت إليهن وأعتدت لهن متكأً وآتت كل واحدة منهن سكينًا وقالت اخرج عليهن فلما رأينه أكبرنه وقطعن أيديهن وقلن حاش لله ما هذا بشرًا إن هذا إلا ملك كريم» (12:31). ثم هددته بالسجن، فدعا يوسف: «رب السجن أحب إلي مما يدعونني إليه» (12:33). ويتعلم المسلم أن يوسف اختار السجن على معصية الله.",

"prophets_179": "يقول يوسف: «يا صاحبي السجن أأرباب متفرقون خير أم الله الواحد القهار ما تعبدون من دونه إلا أسماء سميتموها أنتم وآباؤكم ما أنزل الله بها من سلطان إن الحكم إلا لله» (12:39-40). وكان فتيان قد سألاه تعبير رؤياهما، وقد رأياه من المحسنين (12:36). ويتعلم المسلم أن يقدّم الدعوة إلى توحيد الله على كل خدمة أخرى.",

"prophets_180": "تحفظ سورة يوسف: «وقال الملك ائتوني به أستخلصه لنفسي فلما كلمه قال إنك اليوم لدينا مكين أمين» (12:54). وكان يوسف قد أبى أن يخرج من السجن حتى يتبين أمر النسوة (12:50). وأجاب عرض الملك بطلب: «اجعلني على خزائن الأرض» (12:55). ويتعلم المسلم أن مكانة يوسف جاءت بعد أن ظهرت براءته، وأنه استعملها ليتحمل واجبًا.",

"prophets_181": "تقول سورة يوسف: «فبدأ بأوعيتهم قبل وعاء أخيه ثم استخرجها من وعاء أخيه كذلك كدنا ليوسف ما كان ليأخذ أخاه في دين الملك إلا أن يشاء الله نرفع درجات من نشاء وفوق كل ذي علم عليم» (12:76). والإخوة أنفسهم هم الذين سمّوا الجزاء: من وُجد في رحله فهو جزاؤه (12:75). ويتعلم المسلم أن الله يدبر الأحداث فوق ما يرى البشر.",

"prophets_182": "كلمات يوسف في سورة يوسف: «لا تثريب عليكم اليوم يغفر الله لكم وهو أرحم الراحمين» (12:92). وكان قد سألهم هل علموا ما فعلوا بيوسف وأخيه إذ هم جاهلون (12:89)، ثم قال لهم: «أنا يوسف وهذا أخي» (12:90)؛ فأقرّوا: «لقد آثرك الله علينا وإن كنا لخاطئين» (12:91). ويتعلم المسلم أن العفو عمن ظلمنا، ونحن نملك القدرة عليهم، هو سبيل الأنبياء.",

"prophets_183": "يقول يعقوب في سورة يوسف: «يا بني اذهبوا فتحسسوا من يوسف وأخيه ولا تيأسوا من روح الله إنه لا ييأس من روح الله إلا القوم الكافرون» (12:87). وكانت عيناه حينئذ قد ابيضّت من الحزن (12:84)، وكان بنوه قد قالوا له إنه لا يفتأ يذكر يوسف حتى يكون حرضًا (12:85). ويتعلم المسلم أن الحزن يُرفع إلى الله، وأن الرجاء في فرجه جزء من الإيمان نفسه.",

"prophets_184": "نص الدعاء: «رب قد آتيتني من الملك وعلمتني من تأويل الأحاديث فاطر السماوات والأرض أنت وليي في الدنيا والآخرة توفني مسلمًا وألحقني بالصالحين» (12:101). يقوله يوسف في ذروة قصته، حين جاء أبواه إلى مصر وخرّ أهله له سجدًا (12:100). ويتعلم المسلم من يوسف أن يسأل حسن الخاتمة فوق كل مكسب دنيوي.",

"prophets_185": "تقول سورة ص: «واذكر عبدنا أيوب إذ نادى ربه أني مسني الشيطان بنصب وعذاب» (38:41). وتورد سورة الأنبياء نداءه بالكلمات: «أني مسني الضر وأنت أرحم الراحمين» (21:83). وجاء الجواب في الحال: «اركض برجلك هذا مغتسل بارد وشراب» (38:42). ويتعلم المسلم من أيوب كيف يشكو إلى الله وحده، من غير كلمة عليه.",

"prophets_186": "تقول سورة ص: «ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولي الألباب» (38:43). والآية التي بعدها تضيف شهادة الله: «إنا وجدناه صابرًا نعم العبد» (38:44). وتقول سورة الأنبياء مثله: «فاستجبنا له فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم» (21:84). ويتعلم المسلم أن فرج الله بعد الصبر يأتي أكبر من الخسارة: ما ضاع رُدّ مضاعفًا.",

"prophets_187": "تقول سورة الصافات: «فلولا أنه كان من المسبحين للبث في بطنه إلى يوم يبعثون» (37:143-144). وكان يونس قد أبق إلى الفلك المشحون، فساهم فكان من المدحضين (37:140-141). وتورد سورة الأنبياء كلماته في الظلمات: «لا إله إلا أنت سبحانك إني كنت من الظالمين» (21:87). ويتعلم المسلم أن تسبيح الله في الرخاء يحمل العبد في أشد الأوقات.",

"prophets_188": "تقول سورة يونس: «فلولا كانت قرية آمنت فنفعها إيمانها إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم إلى حين» (10:98). وتعطي سورة الصافات عددهم: مائة ألف أو يزيدون، «فآمنوا» (37:147-148). ويتعلم المسلم أن التوبة قبل نزول العذاب مقبولة، وأن مدينة بأكملها نجت بها.",

"prophets_189": "تقول سورة القلم: «فاصبر لحكم ربك ولا تكن كصاحب الحوت إذ نادى وهو مكظوم لولا أن تداركه نعمة من ربه لنبذ بالعراء وهو مذموم فاجتباه ربه فجعله من الصالحين» (68:48-50). والسورة موجهة إلى النبي ﷺ (68:2). ويتعلم المسلم أن الصبر مطلوب ممن يدعو إلى الله.",

"prophets_190": "تقول سورة الصافات: «وإن إلياس لمن المرسلين إذ قال لقومه ألا تتقون أتدعون بعلًا وتذرون أحسن الخالقين الله ربكم ورب آبائكم الأولين» (37:123-126). فكذبه قومه (37:127)؛ ثم ترك الله عليه في الآخرين تحية: «سلام على إل ياسين» (37:129-130). ويتعلم المسلم أن إلياس دعا إلى عبادة الخالق وحده، وأن السلام الذي أُرسل عليه يُتلى اليوم.",

"prophets_191": "تقول سورة الأنبياء: «وإسماعيل وإدريس وذا الكفل كل من الصابرين وأدخلناهم في رحمتنا إنهم من الصالحين» (21:85-86). وقد ذُكروا مباشرة بعد أيوب الذي حُكي للتوّ صبره في البلاء (21:83-84). ويُذكر ذو الكفل مرة أخرى في سورة ص، إلى جانب إسماعيل أيضًا: «واذكر إسماعيل واليسع وذا الكفل وكل من الأخيار» (38:48). ويتعلم المسلم أن القرآن لا يحكي عنه قصة، وأن الصبر وحده أكسبه مكانًا في رحمة الله.",

"prophets_192": "تقول سورة البقرة: «وإذ فرقنا بكم البحر فأنجيناكم وأغرقنا آل فرعون وأنتم تنظرون» (2:50). وهي من مقطع يبدأ بقوله: «يا بني إسرائيل اذكروا نعمتي التي أنعمت عليكم» (2:40). وتُري سورة الشعراء تلك اللحظة: «اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم» (26:63). ويتعلم المسلم أن الله ينجي ويحكم في فعل واحد، وأن نعمه تُذكر.",

"prophets_193": "يقول موسى في سورة القصص: «وأخي هارون هو أفصح مني لسانًا فأرسله معي ردءًا يصدقني إني أخاف أن يكذبون» (28:34). فأجاب الله: «سنشد عضدك بأخيك ونجعل لكما سلطانًا» (28:35). ويتعلم المسلم أن طلب المعين ليس ضعفًا، وأن الله وهب هارون النبوة استجابة لدعاء أخيه.",

"prophets_194": "يقول الله لموسى وهارون في سورة طه: «فقولا له قولًا لينًا لعله يتذكر أو يخشى» (20:44)، مباشرة بعد «اذهبا إلى فرعون إنه طغى» (20:43). فأجابا: «ربنا إننا نخاف أن يفرط علينا أو أن يطغى»، فقيل لهما: «لا تخافا إنني معكما أسمع وأرى» (20:45-46). ويتعلم المسلم أن اللين في الدعوة إلى الله مأمور به حتى مع أقسى مخاطَب.",

"prophets_195": "تقول سورة غافر: «وقال رجل مؤمن من آل فرعون يكتم إيمانه أتقتلون رجلًا أن يقول ربي الله وقد جاءكم بالبينات من ربكم» (40:28). ويتكلم مباشرة بعد أن قال فرعون «ذروني أقتل موسى» (40:26)، وتختم السورة قصته: «فوقاه الله سيئات ما مكروا» (40:45). ويتعلم المسلم أن مؤمنًا واحدًا يقول الحق أمام طاغية يذكره الله.",

"prophets_196": "تقول سورة طه: «ولقد قال لهم هارون من قبل يا قوم إنما فتنتم به وإن ربكم الرحمن فاتبعوني وأطيعوا أمري» (20:90). وكان السامري قد أخرج لهم عجلًا جسدًا له خوار، فقالوا: «هذا إلهكم وإله موسى» (20:88). ويتعلم المسلم أن الفتنة قد تأتي في ثوب العجيب، وأن اتباع رسول الله، كما طلب هارون، هو طريق النجاة منها.",

"prophets_197": "تقول سورة القصص: «وقالت امرأة فرعون قرة عين لي ولك لا تقتلوه عسى أن ينفعنا أو نتخذه ولدًا وهم لا يشعرون» (28:9). وكان قد أُوحي إلى أم موسى أن تلقيه في اليم (28:7). وفي سورة التحريم تدعو المرأة نفسها: «رب ابن لي عندك بيتًا في الجنة» (66:11). ويتعلم المسلم أن قلبًا مؤمنًا عاش داخل قصر فرعون نفسه.",

"prophets_198": "تحفظ سورة الكهف: «قال له موسى هل أتبعك على أن تعلّمن مما عُلّمت رشدًا» (18:66). ولا يوصف الرجل إلا بأنه «عبدًا من عبادنا آتيناه رحمة من عندنا وعلمناه من لدنا علمًا» (18:65). ووعد موسى: «ستجدني إن شاء الله صابرًا» (18:69). ويتعلم المسلم آداب طلب العلم من موسى، النبي الذي كلّمه الله: يستأذن، ويعد بالصبر، ويضع نفسه تحت المعلم.",

"prophets_199": "تقول سورة الأعراف: «ولما رجع موسى إلى قومه غضبان أسفًا قال بئسما خلفتموني من بعدي… وألقى الألواح وأخذ برأس أخيه يجره إليه» (7:150). فأجاب هارون: «ابن أم إن القوم استضعفوني وكادوا يقتلونني» (7:150)، ودعا موسى: «رب اغفر لي ولأخي» (7:151). ويتعلم المسلم أن الغضب لله حقيقي حتى في نبي، وأنه ينتهي بالدعاء.",

"prophets_200": "تقول سورة النازعات: «اذهب إلى فرعون إنه طغى فقل هل لك إلى أن تزكى وأهديك إلى ربك فتخشى» (79:17-19). وكانت السورة قد ذكّرت للتوّ بنداء موسى بالوادي المقدس طوى (79:15-16). فأجاب فرعون بإعلانه «أنا ربكم الأعلى» (79:24)، فأخذه الله نكالًا (79:25). ويتعلم المسلم أن الطاغية نفسه عُرضت عليه أولًا التزكية والهداية، بسؤال لا بتهديد.",
}
